    slug: "blutbild-beim-aelteren-hund",
    title: "Blutbild beim älteren Hund",
    shortDescription: "Was regelmäßige Laborwerte verraten – die wichtigsten Parameter im Überblick.",
    level: 2,
    tags: ["senior", "blutbild", "labor", "diagnostik"],
    imageUrl: "/images/tipps/senior-hund/7.jpg",
    imageAlt: "Tierarzt hält Blutröhrchen eines Hundes",
    content: `## Warum ein Blutbild für Senioren so wichtig ist

Innere Organe lassen sich von außen nicht direkt beurteilen. Ob Nieren, Leber, Schilddrüse oder Pankreas ihre Arbeit gut erledigen, zeigt sich erst im Blut. Regelmäßige Laborwerte sind deshalb beim älteren Hund ein unverzichtbares Werkzeug der Früherkennung.

Was ein Blutbild beim Seniorhund leisten kann: Es kann Organprobleme erkennen, bevor Symptome sichtbar werden. Es liefert Ausgangswerte, mit denen spätere Ergebnisse verglichen werden können. Und es gibt dem Tierarzt die Grundlage, gezielt zu handeln.

## Die wichtigsten Parameter im Seniorenblutbild

**Nierenwerte:**
- **Kreatinin:** Steigt bei nachlassender Nierenfunktion. Erst erhöht, wenn mehr als 75 % der Nierenfunktion verloren sind.
- **BUN (Blut-Harnstoff-Stickstoff):** Reagiert früher auf Nierenprobleme als Kreatinin, ist aber auch futterabhängig.
- **SDMA:** Neuerer und sensibler Nierenmarker, kann Nierenprobleme bereits bei 25–40 % Funktionsverlust anzeigen.
- **Phosphor:** Erhöhte Werte belasten die Nieren zusätzlich.

**Leberwerte:**
- **ALT (Alanin-Aminotransferase):** Erhöht bei Leberzellschäden.
- **AST (Aspartat-Aminotransferase):** Ebenfalls Leberenzym, reagiert auf Muskel- und Leberschäden.
- **Alkalische Phosphatase (ALP):** Kann auf Leberprobleme oder Cushing-Syndrom hinweisen.
- **GGT:** Marker für Gallengang- und Leberprobleme.

**Blutzucker:**
Erhöhte Glucosewerte können auf Diabetes mellitus hindeuten, erniedrigte auf ein Insulinom.

**Schilddrüse:**
- **T4 (Thyroxin):** Erniedrigt bei Hypothyreose (Schilddrüsenunterfunktion), die bei älteren Hunden häufig vorkommt.

**Blutbild (CBC):**
- **Erythrozyten, Hämoglobin, Hämatokrit:** Anzeichen für Anämie
- **Leukozyten:** Erhöht bei Infektionen oder Entzündungen
- **Thrombozyten:** Relevant für die Blutgerinnung

## Wie oft sollte ein Blutbild gemacht werden?

Bei gesunden Senior-Hunden empfiehlt sich mindestens einmal jährlich ein vollständiges Blutbild. Bei bekannten Erkrankungen oder auffälligen Werten kann der Tierarzt engmaschigere Kontrollen empfehlen.

Der Vorteil: Wenn du über mehrere Jahre Verlaufswerte sammelst, erkennst du Trends, bevor einzelne Werte in einen kritischen Bereich fallen.

## Was tun bei auffälligen Werten?

Ein einzelner auffälliger Wert bedeutet nicht automatisch eine ernste Erkrankung. Viele Werte schwanken je nach Tageszeit, Stresslevel, Futteraufnahme oder Begleitmedikation. Der Tierarzt bewertet die Werte immer im Gesamtbild.

Häufig folgt bei auffälligen Werten:
- Eine Kontrollmessung nach wenigen Wochen
- Weiterführende Diagnostik (Ultraschall, Urinanalyse)
- Ernährungsanpassungen oder medikamentöse Behandlung

## FAQ

**Muss mein Hund nüchtern zur Blutabnahme?**
Für präzise Glukose- und Leberwerte ist Nüchternheit (ca. 8–12 Stunden kein Futter) sinnvoll. Frage deinen Tierarzt vorab.

**Was kostet ein vollständiges Blutbild beim Hund?**
Je nach Praxis und Umfang zwischen 40 und 120 Euro. Ein großes Blutbild mit Schilddrüse kann auch mehr kosten.

**Was bedeutet SDMA und warum ist es besser als Kreatinin?**
SDMA erkennt Nierenprobleme früher als Kreatinin – schon bevor 40 % der Nierenfunktion verloren sind. Das ermöglicht früheres Handeln.

Regelmäßige Laborkontrollen sind eine der wertvollsten Investitionen in die Gesundheit deines älteren Hundes.`,
    seoTitle: "Blutbild beim älteren Hund – wichtige Laborwerte erklärt | BELLA",
