    id: 19,
    slug: "mahlzeiten-aufteilen-im-alter",
    title: "Mahlzeiten aufteilen im Alter",
    shortDescription: "Kleine Portionen mehrmals täglich können für ältere Hunde besser sein als eine große Mahlzeit.",
