    id: 41,
    slug: "vollblutbild-als-basischeck",
    title: "Vollblutbild als Basischeck für Senioren",
    shortDescription: "Warum halbjährliche Blutkontrollen für ältere Hunde so wichtig sind und was das Blutbild zeigt.",
    level: 1,
    tags: ["senior", "blutbild", "vorsorge", "diagnostik", "tierarzt"],
    imageUrl: "/images/tipps/senior-hund/19.jpg",
    imageAlt: "Tierarzt entnimmt Blutprobe bei einem älteren Hund",
    content: `## Das Blutbild – das wichtigste Frühwarn-Instrument

Ein vollständiges Blutbild ist für Seniorhunde das, was eine Routine-Untersuchung für uns Menschen ist: ein systematischer Blick auf den Gesundheitszustand, der Probleme aufdeckt, lange bevor der Hund Symptome zeigt.

Viele schwerwiegende Erkrankungen – Niereninsuffizienz, Leberprobleme, Diabetes, Hormonstörungen, Anämie – haben eine „stille Phase", in der sie behandelbar sind, aber kaum sichtbare Zeichen machen. Ein Blutbild bricht dieses Schweigen.

## Was ein Vollblutbild untersucht

**Großes Blutbild (Hämatologie):**
- Rote Blutkörperchen (Erythrozyten, Hämoglobin, Hämatokrit): erkennt Anämie
- Weiße Blutkörperchen (Leukozyten): zeigt Infektionen, Entzündungen, Immunreaktionen
- Thrombozyten (Blutplättchen): Blutgerinnung

**Biochemieprofil (Serum/Plasma):**
- Nierenwerte: Kreatinin, BUN (Harnstoff), SDMA
- Leberwerte: ALT, AST, alkalische Phosphatase, Bilirubin
- Blutzucker (Glukose)
- Elektrolyte: Natrium, Kalium, Kalzium, Phosphor
- Gesamtprotein, Albumin

**Hormontests (ergänzend):**
- T4 (Schilddrüse)
- Cortisol (Cushing/Addison)

## SDMA – der frühzeitigste Nierenwert

Der SDMA-Test (symmetrisches Dimethylarginin) erkennt Nierenprobleme, wenn noch 25–40 % der Funktion verloren sind – während Kreatinin erst bei 75 % Verlust anschlägt. Das gibt wertvollen Vorsprung für Ernährungsanpassungen und Therapie.

## Wie oft Blutbild beim Senior?

- Gesunder Senior unter 10 Jahren: einmal jährlich
- Ab 10 Jahren oder bekannte Vorerkrankungen: alle 6 Monate
- Hunde in aktiver Behandlung: je nach Erkrankung alle 3 Monate oder häufiger

## Was passiert, wenn Werte auffällig sind?

Nicht jeder auffällige Wert bedeutet sofortige Behandlung. Kontext zählt: Ein leicht erhöhter Leberwert nach Stress oder Medikamentengabe kann bedeutungslos sein. Ein dauerhaft erhöhter Nierenwert erfordert Handeln.

Dein Tierarzt bewertet die Werte immer im Gesamtbild – niemals isoliert.

## FAQ

**Muss mein Hund für das Blutbild nüchtern sein?**
Für genaue Glukose- und Fettwerte ja, meist 8–12 Stunden nüchtern. Frage deinen Tierarzt.

**Kostet ein Blutbild viel?**
Ein vollständiges Seniorenblutbild kostet je nach Praxis 80–200 €. Günstig verglichen mit den Kosten später erkannter Erkrankungen.

**Kann ich das Blutbild zu Hause machen?**
Nein, die Probennahme und Auswertung erfordert Fachpersonal und Labor.

Ein regelmäßiges Blutbild ist keine Panikmaßnahme – es ist vorausschauende Fürsorge.`,
    seoTitle: "Blutbild für Seniorhunde – warum und wie oft | BELLA",
    seoDescription: "Halbjährliche Blutkontrollen retten Leben. Welche Werte beim Seniorhund geprüft werden und was sie verraten.",
