    title: "Wärme im Winter – wie du deinen Seniorhund schützt",
    shortDescription: "Kälte trifft Seniorhunde härter als junge Tiere. Was du im Winter konkret tun kannst, damit dein alter Hund warm und wohlbehalten bleibt.",
    level: 0,
