    title: "Schnüffelspiele für Seniorhunde – die sanfte Beschäftigung",
    shortDescription: "Schnüffeln ist die natürlichste und schonendste Form der Beschäftigung für alte Hunde. Welche Spiele sich bewähren und wie du anfängst.",
